<script setup lang="ts">
import { computed } from 'vue'
import { metric, milliseconds, money, timingSource, percentage, orderSuccess, type OperationsOverview } from '../../operations'
import MetricGrid from './MetricGrid.vue'
import OperationsFreshness from './OperationsFreshness.vue'
import SectionLabel from '../../components/ui/SectionLabel.vue'
const props = defineProps<{ data: OperationsOverview }>()
const business = computed(() => props.data.business), perf = computed(() => props.data.performance)
const values = computed<[string,string][]>(() => { const b = business.value; return [['当日活跃用户',metric(b.activeUsers)],['新增用户',metric(b.newUsers)],['有效面试',metric(b.interviews)],['使用时长', b.usedSeconds === null ? '未知' : `${(b.usedSeconds/3600).toFixed(2)} 小时`],['付费用户',metric(b.paidUsers)],['实付金额',money(b.paidCents)],['退款金额',money(b.refundCents)],['净收款',money(b.netCents)],['订单成功率',orderSuccess(b.orders.paid,b.orders.total)]] })
const performance = computed<[string,string][]>(() => { const p = perf.value; return [['回答操作',metric(p.answers)],['系统错误',metric(p.errors)],['超时',metric(p.timeouts ?? null)],['并发拒绝',metric(p.rejections ?? null)],['失败率',percentage(p.errorRate)],['取消',metric(p.cancellations)],['降级',metric(p.degraded)],['检索降级率',percentage(p.degradedRate)],['首段正文 P95',milliseconds(p.firstContentP95Ms)],['首段正文样本',metric(p.sampleCount)],['客户端报告事件',metric(p.clientReported)],['仅后端事件',metric(p.serverOnly)],['客户端覆盖率','未知'],['明细完整性覆盖','未知'],['Token 覆盖率',percentage(p.tokenCoverage)]] })
</script>
<template><section class="stack" aria-label="业务概览"><div class="page-head"><SectionLabel title="业务概览" /><OperationsFreshness :updated-at="business.updatedAt" :stale="business.stale" /></div><p class="business-caption">来自业务数据库。当日活跃用户为北京时间当天开始面试的普通用户；使用时长仅统计时长账本实际扣除。净收款为实付减退款，不代表利润。</p><MetricGrid :values="values" hero /><p class="business-caption">订单成功率按同一创建时间范围内的已支付订单 / 总订单计算。订单：总计 {{ metric(business.orders.total) }} · 已支付 {{ metric(business.orders.paid) }} · 待支付 {{ metric(business.orders.pending) }} · 已关闭 {{ metric(business.orders.closed) }} · 失败 {{ metric(business.orders.failed) }}</p></section><section class="stack" aria-label="体验概览"><SectionLabel title="回答体验" /><p class="business-caption">首段正文 P95 统计来源：{{ timingSource(perf.firstContentSource) }}。仅后端数据不包括桌面渲染。</p><MetricGrid :values="performance" /><p class="business-caption">失败率仅计系统错误与超时，分母：{{ perf.errorRateDenominator === 'canonical_attempts_excluding_cancelled_skipped_rejected' ? `${metric(perf.errorRateSamples ?? null)} 个排除取消、跳过、拒绝的回答终态样本` : '未知' }}。检索降级率分母为 {{ metric(perf.retrievalCount ?? null) }} 次检索请求，来源：{{ timingSource(perf.retrievalSource) }}。Token 覆盖率分母为 {{ metric(perf.llmSamples ?? null) }} 个同来源 LLM 样本，来源：{{ timingSource(perf.tokenSource) }}；仅供应商实际返回 usage 的样本计入覆盖。</p><p class="business-caption">客户端覆盖率与完整性缺少可核验分母，显示未知；原始事件数不等于用户覆盖率。客户端报告为客户端自行上报；仅后端数据无法覆盖渲染与自定义服务。Token 用量有 {{ metric(perf.tokenSamples) }} 条供应商实际返回样本，不据此推算费用。{{ perf.sampleCount !== null && perf.sampleCount < 20 ? '样本不足 20，分位数仅供参考。' : '' }}</p></section></template>
